import {updateMarkup,taskAppearance,priorityIndicator} from './rendering.js';
import {STATUS_LABELS,openItem} from './domain.js';
import {PlanningPreferences,PLANNING_KEY,dueReminders,postpone,reminderDate,validZone} from './planning.js';
import {createPushUI} from './push-ui.js';
import {checkForm,submitOnce} from './forms.js';
export function createPlanningUI({storage,getState,icon,esc,openModal,closeModal,toast,onOpen,onEdit,onComplete,onClockChange=()=>{},target=window,now=()=>new Date(),appUrl=new URL('./',target.location.href).href}){
  const preferences=new PlanningPreferences(storage);let visible=60,timer,renderTime=null,reminderCache=null;
  const prefs=()=>preferences.value;
  const push=createPushUI({storage,getState,getPreferences:prefs,target,esc,icon,toast,openModal,closeModal,onChange:()=>onOpen?.(false)});
  const option=(value,label,current)=>`<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(label)}</option>`;
  const check=(id,label,checked)=>`<label class="planning-check" for="${id}"><input type="checkbox" id="${id}" ${checked?'checked':''}><span>${label}</span></label>`;
  function beginRender(instant=now()){renderTime=instant;reminderCache=null}
  const items=()=>{const state=getState(),settings=prefs();if(!reminderCache||reminderCache.state!==state||reminderCache.clock!==state.clock||reminderCache.settings!==settings){reminderCache={state,clock:state.clock,settings,items:dueReminders(state,settings,renderTime||now())}}return reminderCache.items};
  function header(){const list=items();return `<button type="button" class="reminder-trigger" data-action="planning-open" aria-label="Lembretes: ${list.length} ${list.length===1?'prazo próximo ou atrasado':'prazos próximos ou atrasados'}" title="Lembretes">${icon('bell')}${list.length?`<span class="reminder-count" aria-hidden="true">${list.length>99?'99+':list.length}</span>`:''}</button>`}
  function summaryContent(){const list=items();if(!list.length)return '';const late=list.filter(x=>x.overdue).length;return `<button class="reminder-summary ${late?'has-overdue':''}" data-action="planning-open">${icon('bell')}<span><strong>${late?late+' '+(late===1?'prazo atrasado':'prazos atrasados'):list.length+' '+(list.length===1?'prazo próximo':'prazos próximos')}</strong><small>Abrir lembretes</small></span>${icon('right')}</button>`}
  const summary=()=>`<div id="planning-summary">${summaryContent()}</div>`;
  function reminderRows(){const list=items(),show=list.slice(0,visible),state=getState();if(!prefs().reminders.enabled)return `<div class="empty"><h2>Lembretes desativados</h2><p>Ative os avisos para acompanhar os prazos dos seus itens e subitens.</p><button class="btn primary" data-action="planning-reminder-settings">Configurar lembretes</button></div>`;
    if(!list.length)return `<div class="empty"><span class="emptyicon">${icon('bell')}</span><h2>Nenhum prazo para lembrar agora</h2><p>Itens e subitens em aberto aparecem aqui de acordo com suas próprias datas. Concluídos, cancelados e itens sem data ficam fora dos avisos.</p><button class="btn secondary" data-action="planning-reminder-settings">Ajustar lembretes</button></div>`;
    return `<div class="reminder-list">${show.map(entry=>{const t=entry.item,parent=t.parentId?state.items[t.parentId]:null;return `<article class="reminder-card reminder-content priority-${t.priority}" ${taskAppearance(t,state.areas)}><div class="task-head"><button class="taskcheck ${t.status}" data-action="planning-complete" data-id="${esc(t.id)}" aria-label="Concluir: ${esc(t.title)}"><span class="checkbox">${t.status==='doing'?'<i></i>':''}</span></button><h2 class="reminder-title">${esc(t.title)}</h2><button class="manage-task" data-action="planning-edit" data-id="${esc(t.id)}" aria-label="Gerenciar: ${esc(t.title)}" title="Gerenciar tarefa e aviso">${icon('gear')}<span class="sr-only">Gerenciar</span></button></div><div class="task-information"><time class="reminder-date ${entry.overdue?'late':''}" datetime="${esc(t.date+(t.time?'T'+t.time:''))}">${icon('calendar')}<span>${esc(reminderDate(entry,renderTime||now(),prefs().timeZone))}</span></time><span class="task-area-label">${esc(state.areas[t.areaId]?.name??'Sem área')}</span></div><div class="task-tags">${priorityIndicator(t.priority)}<span class="task-status-label" aria-label="Andamento: ${esc(STATUS_LABELS[t.status])}">${t.status==='doing'?'◷ ':''}${esc(STATUS_LABELS[t.status])}</span></div>${parent?`<p class="reminder-context">Subitem de ${esc(parent.title)}</p>`:''}</article>`}).join('')}</div>${list.length>visible?`<div class="collection-more"><p>${visible} de ${list.length} lembretes</p><button class="btn secondary" data-action="planning-more">Mostrar mais 60</button></div>`:''}`;
  }
  function page(){return `<div class="page-heading"><div><h1>Lembretes</h1><p>Seus próximos prazos. Use a engrenagem para editar a tarefa ou adiar o aviso.</p></div></div><div class="reminder-toolbar"><button class="textbtn" data-action="page" data-page="plan">${icon('left')} Planejamento</button><button class="textbtn" data-action="planning-reminder-settings">${icon('settings')} Configurar central</button></div><div id="reminders-results">${reminderRows()}</div>`}
  function settings(){const r=prefs().reminders;return `${preferences.error?`<p class="planning-warning" role="status">${esc(preferences.error)}</p>`:''}<section class="settingscard"><div class="settings-heading"><span class="settings-icon">${icon('bell')}</span><div><h2>Central de lembretes</h2><p>Avisos que aparecem no sino, dentro do aplicativo.</p></div></div><p>${r.enabled?'Avisos ativos dentro do Retomar.':'Avisos internos desativados.'}</p><button class="btn secondary" data-action="planning-reminder-settings">Configurar lembretes ${icon('arrow')}</button></section>${push.settings()}`}
  function save(next){preferences.save(next);refresh();return next}
  function reminderSettings(){const r=prefs().reminders,root=openModal('Configurar central de lembretes',`<form id="reminder-settings-form"><div class="formerror" role="alert"></div><p class="settings-intro">Estas opções controlam a lista do sino. As notificações com o app fechado têm configurações separadas.</p><fieldset class="reminder-settings-group"><legend>1. Mostrar na central</legend>${check('reminders-enabled','Mostrar lembretes dentro do Retomar',r.enabled)}</fieldset><fieldset class="reminder-settings-group"><legend>2. Quais prazos exibir</legend><div class="field"><label for="reminders-days">Incluir tarefas com prazo até</label><select id="reminders-days">${[[0,'Somente hoje'],[1,'Hoje e amanhã'],[3,'3 dias a partir de hoje'],[7,'7 dias a partir de hoje'],[14,'14 dias a partir de hoje'],[30,'30 dias a partir de hoje']].map(([v,l])=>option(v,l,r.aheadDays)).join('')}</select></div>${check('reminders-overdue','Incluir tarefas atrasadas',r.overdue)}<p class="field-help">O prazo da tarefa não muda. Este filtro decide apenas o que aparece na central.</p></fieldset><fieldset class="reminder-settings-group"><legend>3. Ao tocar em Adiar</legend><div class="field"><label for="reminders-snooze">Voltar a mostrar o aviso depois de</label><select id="reminders-snooze">${[[15,'15 minutos'],[30,'30 minutos'],[60,'1 hora'],[180,'3 horas'],[1440,'24 horas']].map(([v,l])=>option(v,l,r.snoozeMinutes)).join('')}</select></div><p class="field-help">Adiar oculta o aviso por esse período. Ocultar até amanhã mantém o aviso fora da central até o início do próximo dia. Nenhuma dessas ações conclui ou arquiva a tarefa.</p></fieldset><details class="settings-details"><summary>Fuso horário e reativação de avisos</summary><div class="field"><label for="reminders-zone">Fuso dos prazos</label><input id="reminders-zone" required maxlength="100" value="${esc(prefs().timeZone)}"></div><button class="textbtn" type="button" id="clear-reminder-dismissals">Reativar avisos ocultos e adiados</button><p class="field-help">Ao salvar, todos os avisos elegíveis voltam a aparecer na central.</p></details><div class="dialogactions"><button class="btn secondary" type="button" id="cancel-planning-settings">Cancelar</button><button class="btn primary" type="submit">Salvar lembretes</button></div><p class="field-help save-note">Preferências salvas neste aparelho.</p></form>`);
    let clear=false;root.querySelector('#clear-reminder-dismissals').onclick=e=>{clear=true;e.target.textContent='Avisos serão reativados ao salvar.';root.querySelector('#reminders-enabled').dispatchEvent(new Event('change',{bubbles:true}))};root.querySelector('#cancel-planning-settings').onclick=()=>closeModal();root.querySelector('form').onsubmit=submitOnce(async e=>{try{const zone=root.querySelector('#reminders-zone');zone.setCustomValidity(validZone(zone.value.trim())?'':'Informe um fuso válido, por exemplo America/Sao_Paulo.');if(!checkForm(e.target))return;const next=structuredClone(prefs());next.timeZone=zone.value.trim();next.reminders={enabled:root.querySelector('#reminders-enabled').checked,aheadDays:Number(root.querySelector('#reminders-days').value),overdue:root.querySelector('#reminders-overdue').checked,snoozeMinutes:Number(root.querySelector('#reminders-snooze').value)};if(clear)next.dismissals={};save(next);closeModal(true);toast('Lembretes configurados neste aparelho.');onOpen?.(false)}catch(error){const errorNode=root.querySelector('.formerror');errorNode.textContent=error.message;errorNode.scrollIntoView({block:'nearest'})}});
  }
  function refresh(){beginRender();push.sync();const bell=target.document.querySelector('.reminder-trigger');if(bell){const count=items().length;bell.setAttribute('aria-label','Lembretes: '+count+' '+(count===1?'prazo próximo ou atrasado':'prazos próximos ou atrasados'));let badge=bell.querySelector('.reminder-count');if(count){if(!badge){badge=target.document.createElement('span');badge.className='reminder-count';badge.setAttribute('aria-hidden','true');bell.append(badge)}badge.textContent=count>99?'99+':String(count)}else badge?.remove()}const summary=target.document.querySelector('#planning-summary');if(summary){const content=summaryContent();updateMarkup(summary,content);}const result=target.document.querySelector('#reminders-results');if(result&&!target.document.activeElement?.closest('#reminders-results'))updateMarkup(result,reminderRows());}
  function reload(){preferences.reload();refresh()}

  const refreshWhenIdle=()=>{
    if(target.document.hidden||target.document.querySelector('dialog[open]')||target.document.documentElement.classList.contains('drag-active')||target.document.activeElement?.matches('input,textarea,select'))return;
    refresh();onClockChange();
  };
  const storageChanged=e=>{if(e.key===PLANNING_KEY){reload();if(!target.document.querySelector('dialog[open]'))onOpen?.(false)}};
  async function action(name,data){try{if(name==='planning-open'){visible=60;onOpen(true)}else if(name==='planning-reminder-settings')reminderSettings();else if(name.startsWith('planning-push-'))await push.action(name,data);else if(name==='planning-edit')onEdit(data.id);else if(name==='planning-complete')await onComplete(data.id);else if(name==='planning-snooze'||name==='planning-dismiss'){const t=getState().items[data.id];if(!t||t.deleted||!openItem(t))return;const before=structuredClone(prefs());save(postpone(prefs(),t,now(),name==='planning-dismiss'));const result=target.document.querySelector('#reminders-results');if(result)updateMarkup(result,reminderRows());toast(name==='planning-dismiss'?'Aviso oculto até amanhã. A tarefa permanece no planejamento.':'Aviso adiado neste aparelho.',{label:'Desfazer',run:()=>{try{const next=structuredClone(prefs());if(before.dismissals[data.id])next.dismissals[data.id]=before.dismissals[data.id];else delete next.dismissals[data.id];save(next);if(result?.isConnected)updateMarkup(result,reminderRows())}catch(e){toast(e.message)}}})}else if(name==='planning-more'){visible+=60;const result=target.document.querySelector('#reminders-results');if(result)updateMarkup(result,reminderRows())}}catch(error){toast(error.message)}
  }
  return {beginRender,timeZone:()=>prefs().timeZone,itemPushButton:t=>push.itemButton(t),syncPush:()=>push.sync(),header,summary,page,settings,action,refresh,reload,start(){push.start();target.addEventListener('storage',storageChanged);target.addEventListener('focus',refreshWhenIdle);target.document.addEventListener('visibilitychange',refreshWhenIdle);timer=target.setInterval(refreshWhenIdle,30000)},dispose(){push.dispose();target.clearInterval(timer);target.removeEventListener('storage',storageChanged);target.removeEventListener('focus',refreshWhenIdle);target.document.removeEventListener('visibilitychange',refreshWhenIdle)}};
}
